import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-110: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short110', durationInSeconds: 34.1, fps: 30, width: 1080, height: 1920 };


const B1 = secToFrame(2.2);
const B2 = secToFrame(6.6);
const B3 = secToFrame(11.6);
const B4 = secToFrame(22.9);
const CTA = secToFrame(31.4);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short110: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-110/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="TRANSCRIPTION PRICE" lines={[{ text: 'OPENAI 27¢/HR' },{ text: 'GOOGLE 18¢/HR', accent: true }]} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="GPT Transcribe" tagline="OpenAI list price." chip="27¢ / HOUR" at={B1 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="per minute" v="$0.0045" bad />
            <Line k="per hour" v="$0.27" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="Gemini 3.5 Transcribe" tagline="Google list price." chip="18¢ / HOUR" at={B2 + 4}>
          <Panel>
            <Line k="per minute" v="$0.003" good />
            <Line k="per hour" v="$0.18" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="10 hours of audio" tagline="Google is 1.5x cheaper." chip="$2.70 vs $1.80" at={B3 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="OpenAI" v="$2.70" bad />
            <Line k="Google" v="$1.80" good />
            <Line k="free tier" v="yes, rate-limited" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Price only" tagline="Accuracy not compared." chip="TEST YOURS" at={B4 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="OpenAI /hr" v="27¢" bad />
            <Line k="Google /hr" v="18¢" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-110/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="TRANSCRIPTION PRICE" lines={[{ text: 'OPENAI 27¢/HR' },{ text: 'GOOGLE 18¢/HR', accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Eighteen beats twenty seven.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short110;
